diff --git a/src/ops/linear/w8/w8_dispatch.cpp b/src/ops/linear/w8/w8_dispatch.cpp
index be875f97..eb1bef6e 100644
--- a/src/ops/linear/w8/w8_dispatch.cpp
+++ b/src/ops/linear/w8/w8_dispatch.cpp
@@ -65,7 +65,7 @@ W8Launch select_w8_a16_launch(std::int32_t n, std::int32_t k, std::int32_t t) {
             if (t == 40) { return launch_w8_mma_r64x16_c48_k128_a1; }
 #endif
 #if defined(GINFER_COMPILED_CC) && GINFER_COMPILED_CC == 89
-            if (t <= 40) { return launch_w8_mma_r64_c40_k128_a1; }
+            if (t <= 40) { return launch_w8_mma_r64_c40_k128_a2; }
             if (t <= 48) { return launch_w8_mma_r64x16_c48_k128_a1; }
 #endif
             return launch_w8_mma_r64_c128;
