 void launch_w8_mma_r64x16_c32_k128_a1(const Tensor&, const Weight&, Tensor&, cudaStream_t);
 void launch_w8_mma_r64x16_c48_k128_a1(const Tensor&, const Weight&, Tensor&, cudaStream_t);
-void launch_w8_mma_r64_c40_k128_a1(const Tensor&, const Weight&, Tensor&, cudaStream_t);
+void launch_w8_mma_r64_c40_k128_a2(const Tensor&, const Weight&, Tensor&, cudaStream_t);

 void launch_w8_exact_mma_r32_c96(const Tensor&, const Weight&, Tensor&, cudaStream_t);
 void launch_w8_exact_mma_r32_c128(const Tensor&, const Weight&, Tensor&, cudaStream_t);
diff --git a/src/ops/linear/w8/w8_rowsplit_gemm_mma.cu b/src/ops/linear/w8/w8_rowsplit_gemm_mma.cu
