-using MmaR64C40K128A1    = W8RowSplitMmaGemmSchedule<64, 40, 32, 8, 2, 2, 128, 1>;
+using MmaR64C40K128A2    = W8RowSplitMmaGemmSchedule<64, 40, 32, 8, 2, 2, 128, 2>;

 } // namespace

@@ -107,7 +107,7 @@ GINFER_W8_MMA_LAUNCHER(launch_w8_mma_r128_c64, MmaR128C64)
 GINFER_W8_MMA_LAUNCHER(launch_w8_mma_r128_c80, MmaR128C80)
 GINFER_W8_MMA_LAUNCHER(launch_w8_mma_r64x16_c32_k128_a1, MmaR64x16C32K128A1)
 GINFER_W8_MMA_LAUNCHER(launch_w8_mma_r64x16_c48_k128_a1, MmaR64x16C48K128A1)
-GINFER_W8_MMA_LAUNCHER(launch_w8_mma_r64_c40_k128_a1, MmaR64C40K128A1)
+GINFER_W8_MMA_LAUNCHER(launch_w8_mma_r64_c40_k128_a2, MmaR64C40K128A2)

 #undef GINFER_W8_MMA_LAUNCHER

